(()=>{
if(window.THCloud){THCloud.start();return;}
const ACCOUNTS_KEY='top-hills-demo-accounts-v1',SESSION_KEY='top-hills-demo-session-v1',DEMO_PASSWORD='TopHills!Demo26';
let state={version:1,accounts:[],events:[]},session='',view='signin',chosen='Owner',ready=false,initError='',storyCleanup=()=>{};
try{const raw=localStorage.getItem(ACCOUNTS_KEY);if(raw){const v=JSON.parse(raw);if(v.version!==1||!Array.isArray(v.accounts)||!Array.isArray(v.events)||v.accounts.some(a=>!a.id||!a.email||!a.hash||!a.salt))throw Error('Format akun tidak valid.');state=v;}session=sessionStorage.getItem(SESSION_KEY)||'';}catch(e){initError='Data akun demo belum bisa dibaca. Gunakan browser dengan penyimpanan lokal aktif.';}
const h=esc;
function save(){localStorage.setItem(ACCOUNTS_KEY,JSON.stringify(state));}
function event(text){state.events.unshift({id:uid('ACC'),at:new Date().toISOString(),actor:current()?.name||'Pengunjung demo',text});}
function current(){const a=state.accounts.find(a=>a.id===session&&a.status==='Aktif');if(!a)return null;if(a.role==='Operator'&&!db.employees.some(e=>e.id===a.employeeId&&e.active))return null;if(a.role==='Konsumen'&&!db.tenants.some(t=>t.id===a.tenantId&&t.status==='Aktif'))return null;return a;}
function bind(){const a=current();if(a){ui.role=a.role;if(a.employeeId)ui.employee=a.employeeId;if(a.tenantId)ui.consumer=a.tenantId;}return a;}
function owner(){if(current()?.role!=='Owner')throw Error('Persetujuan dan perubahan akses hanya tersedia untuk Owner.');}
function hex(bytes){return Array.from(new Uint8Array(bytes),b=>b.toString(16).padStart(2,'0')).join('');}
async function hash(password,salt){if(!globalThis.crypto?.subtle)throw Error('Browser ini belum mendukung penyimpanan kata sandi demo. Buka dengan browser terbaru.');const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveBits']);return hex(await crypto.subtle.deriveBits({name:'PBKDF2',salt:new TextEncoder().encode(salt),iterations:120000,hash:'SHA-256'},key,256));}
async function makeAccount(data,password){const salt=hex(crypto.getRandomValues(new Uint8Array(16)));return {...data,salt,hash:await hash(password,salt),createdAt:new Date().toISOString()};}
function nav(mode){storyCleanup();view=mode;location.hash=mode==='signup'?'daftar':'masuk';render();window.scrollTo({top:0,behavior:'auto'});document.querySelector('.auth-panel h2')?.focus({preventScroll:true});}
const brand=()=>`<a class="brand" href="#masuk" data-access="nav" data-id="signin"><span class="brand-name">top hills<span class="brand-star">✳</span></span><span class="brand-sub">& co. <i>service journal</i></span></a>`;
function password(label='Kata sandi demo',name='password',autocomplete='current-password'){return `<label class="field"><span>${label}</span><span class="password-field"><input name="${name}" type="password" autocomplete="${autocomplete}" minlength="10" maxlength="100" required placeholder="Minimal 10 karakter"><button type="button" data-access="password" aria-label="Tampilkan ${label.toLowerCase()}">Lihat</button></span></label>`;}
function form(){if(!ready)return `<div class="auth-kicker"><span class="eyebrow">RUANG AKUN DEMO</span>${icon('shield')}</div><h2 tabindex="-1">Selamat datang.</h2><p class="auth-intro" role="status">${h(initError||'Menyiapkan akun contoh di browser ini…')}</p>`;
if(view==='success')return `<div class="auth-kicker"><span class="eyebrow">PERMINTAAN TERCATAT</span>${icon('shield')}</div><div class="request-success" role="status">${icon('check')}<h2 tabindex="-1">Satu langkah lagi.</h2><p>Permintaan akun demo tersimpan di browser ini. Owner perlu meninjau dan menghubungkannya dengan profil karyawan atau penghuni sebelum akun bisa dipakai.</p><p><b>Tidak ada email yang dikirim.</b> Untuk mencoba persetujuan, masuk dengan akun contoh Owner lalu buka <b>Akses akun</b>.</p></div><div class="auth-bottom"><button data-access="nav" data-id="signin">Kembali ke halaman masuk ${icon('arrow')}</button></div>`;
const signup=view==='signup';return `<div class="auth-kicker"><span class="eyebrow">${signup?'MULAI TERHUBUNG':'RUANG KERJA BERSAMA'}</span>${icon('shield')}</div><h2 tabindex="-1">${signup?'Bergabung di Top Hills.':'Senang kamu kembali.'}</h2><p class="auth-intro">${signup?'Ajukan akun demo. Owner meninjau setiap akses sebelum mengaktifkannya.':'Masuk untuk melihat pekerjaan, laporan, atau catatan tinggalmu.'}</p><div class="auth-tabs" role="tablist" aria-label="Halaman akun"><button role="tab" aria-selected="${!signup}" data-access="nav" data-id="signin">Masuk</button><button role="tab" aria-selected="${signup}" data-access="nav" data-id="signup">Daftar akun</button></div><form class="auth-form" data-access-form="${signup?'signup':'signin'}">${signup?field('Nama fiktif','name','text','','required maxlength="60" autocomplete="off" placeholder="Contoh: Dita Demo"'):''}${field('Email demo','email','email',signup?'':(chosen==='Owner'?'owner':chosen==='Operator'?'mira':'alya')+'@tophills.example','required maxlength="100" autocomplete="username" placeholder="nama@tophills.example"')}${signup?select('Akses yang diajukan','role',[['Operator','Operator · ruang kerja internal'],['Konsumen','Konsumen · portal pribadi']],'Operator'):''}${password('Kata sandi demo','password',signup?'new-password':'current-password')}${signup?password('Ulangi kata sandi','confirm','new-password'):''}${signup?`<label class="check"><input type="checkbox" name="demo" required><span>Saya menggunakan identitas dan kata sandi fiktif untuk mencoba demo ini.</span></label>`:`<div class="auth-options"><span>Sesi berlaku di tab browser ini.</span><button type="button" data-access="recovery">Lupa kata sandi?</button></div>`}<div class="form-error" role="alert"></div><button type="submit" class="btn primary">${signup?'Ajukan akun demo':'Masuk ke ruang demo'} ${icon('arrow')}</button></form>${signup?`<p class="auth-disclosure">Gunakan email berakhiran <code>@tophills.example</code>. Peran Owner tidak tersedia melalui pendaftaran. Permintaan hanya tersimpan pada browser ini.</p>`:`<div class="demo-divider">Coba akun yang sudah disiapkan</div><div class="demo-roles">${[['Owner','building'],['Operator','laundry'],['Konsumen','home']].map(([r,ic])=>`<button class="${chosen===r?'selected':''}" data-access="fill" data-id="${r}" aria-label="Isi kredensial demo ${r}">${icon(ic)}<span>${r}</span></button>`).join('')}</div><p class="auth-disclosure">Klik peran untuk mengisi akun contoh. Kata sandi: <code>${DEMO_PASSWORD}</code>. Login ini simulasi lokal; gunakan hanya data fiktif.</p>`}`;}
function story(){return `<section class="story-shell" id="cerita" aria-label="Perjalanan layanan Top Hills"><div class="story-stage"><div class="story-top"><span>TOP HILLS & CO / THE EVERYDAY CARE</span><a href="#masuk" data-access="skip">Lewati cerita ↑</a></div><div class="story-composition"><div class="story-copy-stack">${TH_CONTENT.scenes.map((s,i)=>`<article class="story-copy ${i===0?'active':''}"><span class="eyebrow">${h(s.number)} / ${h(s.label)}</span><h2>${h(s.title)}</h2><p>${h(s.body)}</p><small>${h(s.detail)}</small></article>`).join('')}</div><div class="story-subject"><img src="${basketSrc}" width="550" height="550" alt="Keranjang laundry Top Hills yang sama mengikuti perjalanan layanan" loading="lazy"><span class="story-index" aria-hidden="true">01</span></div></div><div class="story-progress" aria-hidden="true"><span>GULIR UNTUK MELANJUTKAN</span><span class="story-track"><i></i></span><span class="story-count">01 / 03</span></div></div></section><div class="story-close"><div><h2>Ruang yang rapi untuk hari yang sibuk.</h2><p>Laundry, hunian, dan laporan tim dalam satu jurnal.</p></div><a href="#masuk" class="btn primary" data-access="skip">Kembali ke halaman masuk ${icon('arrow')}</a></div>`;}
function renderAccess(){storyCleanup();document.body.classList.add('on-entry');app.innerHTML=`<div class="entry"><a href="#auth-form" class="skip-link">Langsung ke formulir</a><header class="entry-nav">${brand()}<span class="entry-edition">${h(TH_CONTENT.edition)}</span><nav class="entry-nav-right"><a href="#cerita">Cerita layanan</a><button class="btn ghost" data-access="nav" data-id="${view==='signup'?'signin':'signup'}">${view==='signup'?'Masuk':'Daftar akun'} ${icon('arrow')}</button></nav></header><main class="entry-main" id="masuk"><section class="entry-cover"><span class="eyebrow">LAUNDRY · LIVING · PEOPLE</span><h1>${h(TH_CONTENT.heading).replace('mulai dari sini.','<br><em>mulai dari sini.</em>')}</h1><p>${h(TH_CONTENT.intro)}</p><a class="entry-story-link" href="#cerita">Kenali cara kami bekerja ${icon('arrow')}</a><div class="cover-still"><img src="${basketSrc}" alt="Keranjang laundry krom, handuk putih, dan pakaian biru" width="510" height="510"><span class="cover-stamp">A LITTLE CARE, EVERY DAY<strong>handled with care.</strong></span></div><div class="cover-caption"><span>01 / THE EVERYDAY ESSENTIALS</span><span>TOP HILLS & CO</span></div></section><section class="auth-panel" id="auth-form" aria-label="Masuk dan daftar akun">${form()}</section></main>${story()}<footer class="entry-footer"><span>© 2026 Top Hills & Co · Pengalaman demo</span><span>Data fiktif · Tersimpan di browser ini</span><a href="style-tile.html" target="_blank" rel="noopener" class="style-tile-link">Design board ↗</a></footer></div>`;startStory();}
function startStory(){const shell=document.querySelector('.story-shell');if(!shell)return;const reduced=matchMedia('(prefers-reduced-motion: reduce)'),constrained=navigator.connection?.saveData||(navigator.deviceMemory&&navigator.deviceMemory<2);const img=shell.querySelector('img'),copies=[...shell.querySelectorAll('.story-copy')];let raf=0;
const paint=()=>{raf=0;if(reduced.matches||constrained){shell.classList.add('story-static');copies.forEach(c=>{c.classList.add('active');c.style.opacity='1';c.style.transform='none';c.removeAttribute('aria-hidden')});img.style.transform='none';return;}shell.classList.remove('story-static');const distance=Math.max(1,shell.offsetHeight-innerHeight),p=Math.max(0,Math.min(1,-shell.getBoundingClientRect().top/distance)),t=THMotion.sample(p),i=t.scene;copies.forEach((c,n)=>{c.classList.toggle('active',i===n);c.style.opacity=i===n?String(t.opacity):'0';c.style.transform=`translateY(${i===n?t.textY:18}px)`;c.setAttribute('aria-hidden',i===n?'false':'true')});img.style.transform=`translate(${t.x}%,${t.y}px) rotate(${t.rotate}deg) scale(${t.scale})`;shell.style.setProperty('--story-progress',p*100+'%');shell.querySelector('.story-index').textContent=String(i+1).padStart(2,'0');shell.querySelector('.story-count').textContent=`0${i+1} / 03`;};const request=()=>{if(!raf)raf=requestAnimationFrame(paint)};window.addEventListener('scroll',request,{passive:true});window.addEventListener('resize',request,{passive:true});reduced.addEventListener('change',request);paint();storyCleanup=()=>{window.removeEventListener('scroll',request);window.removeEventListener('resize',request);reduced.removeEventListener('change',request);if(raf)cancelAnimationFrame(raf)};}
function widget(){const a=current();if(!a)return '';return `<button class="portal-identity" data-access="profile" aria-label="Akun ${h(a.name)}"><span class="avatar small">${h(initials(a.name))}</span><span>${h(a.name.split(' ')[0])}<small>${h(a.role)}</small></span>${icon('down')}</button>`;}
function profile(){const a=current();if(!a)return;openModal('Akun saya',`<div class="access-card"><span class="avatar large blue">${h(initials(a.name))}</span><div><h3>${h(a.name)}</h3><p>${h(a.email)}</p>${badge(a.role,'blue')} ${badge('Akun demo lokal','neutral')}</div></div><p class="access-note section-gap">Akun dan aktivitas demo disimpan di browser ini. Tidak ada email, pembayaran, atau data pelanggan sungguhan.</p><div class="button-row">${a.role==='Owner'?'<button class="btn primary" data-access="manage">Kelola akses akun</button>':''}<button class="btn" data-access="signout">Keluar dari akun</button></div>`);}
function manage(){owner();openModal('Akses akun',`<p class="muted">Owner meninjau permintaan, menghubungkan profil, dan mencabut akses. Riwayat akun tetap disimpan.</p><div class="notice blue">${icon('shield')}Simulasi tata kelola akses SOP v0.3. Setiap operator memakai akun sendiri; konsumen hanya membuka portal pribadi.</div><div class="access-list">${state.accounts.map(a=>`<section class="access-card"><span class="avatar blue">${h(initials(a.name))}</span><div><h3>${h(a.name)}</h3><p>${h(a.email)} · ${h(a.role)}</p>${badge(a.status,a.status==='Aktif'?'green':a.status==='Menunggu'?'yellow':'neutral')}<p>${a.role==='Owner'?'Akun Owner contoh':a.role==='Operator'?'Profil karyawan: '+h(db.employees.find(e=>e.id===a.employeeId)?.name||'Belum dihubungkan'):'Penghuni: '+h(getTenant(a.tenantId)?.name||'Belum dihubungkan')}</p>${a.role!=='Owner'?`<div class="button-row"><button class="btn small" data-access="review" data-id="${a.id}">${a.status==='Aktif'?'Perbarui akses':'Tinjau / aktifkan'}</button>${a.status==='Aktif'?`<button class="text-btn danger" data-access="revoke" data-id="${a.id}">Nonaktifkan</button>`:''}</div>`:'<small>Akun Owner awal tidak dapat dinonaktifkan dari demo.</small>'}</div></section>`).join('')}</div><section class="section-gap"><h3>Riwayat akses</h3>${state.events.slice(0,12).map(e=>`<div class="audit-entry"><strong>${h(e.text)}</strong><p>${h(e.actor)} · ${datetime(e.at)}</p></div>`).join('')||'<p class="access-note">Belum ada perubahan akses.</p>'}</section><div class="button-row section-gap"><button class="btn" data-access="export">Ekspor arsip akun demo</button><button class="btn" data-access="import">Pulihkan arsip akun</button><input type="file" id="access-import" accept="application/json,.json" hidden></div><p class="access-note">Arsip akun terpisah dari cadangan data operasional. Simpan keduanya untuk berpindah browser. Arsip memuat hash kata sandi demo.</p>`,true);}
function review(id){owner();const a=state.accounts.find(a=>a.id===id);if(!a||a.role==='Owner')throw Error('Akun tidak bisa diperbarui.');const options=a.role==='Operator'?db.employees.filter(e=>e.active).map(e=>[e.id,e.name]):db.tenants.filter(t=>t.status==='Aktif').map(t=>[t.id,t.name+' · '+t.room]);openModal('Tinjau akses '+h(a.name),`<form class="auth-form" data-access-form="approve" data-id="${a.id}"><p>${h(a.email)} · ${h(a.role)}</p>${select(a.role==='Operator'?'Hubungkan ke karyawan':'Hubungkan ke penghuni','profileId',options,a.employeeId||a.tenantId,'required')}${field('Nama tampilan fiktif','name','text',a.name,'required maxlength="60"')}${area('Alasan persetujuan / perubahan','reason','','required minlength="5" maxlength="300"')}${check('Identitas demo dan lingkup akses telah ditinjau','approved')}<div class="form-error" role="alert"></div><button class="btn primary" type="submit">Simpan dan aktifkan akun ${icon('check')}</button></form>`);}
function validatePassword(p){if(p.length<10||p.length>100||!/[A-Za-z]/.test(p)||!/[0-9]/.test(p))throw Error('Gunakan 10–100 karakter dengan huruf dan angka untuk kata sandi demo.');}
async function submit(formEl){const v=Object.fromEntries(new FormData(formEl)),type=formEl.dataset.accessForm;const submitBtn=formEl.querySelector('[type=submit]');submitBtn.disabled=true;const error=formEl.querySelector('.form-error');error.textContent='';const snapshot=JSON.stringify(state),oldSession=session;try{
if(type==='signin'){const email=String(v.email).trim().toLowerCase(),a=state.accounts.find(a=>a.email===email);if(!a||await hash(v.password,a.salt)!==a.hash)throw Error('Email atau kata sandi demo belum cocok. Coba akun contoh di bawah.');if(a.status!=='Aktif')throw Error(a.status==='Menunggu'?'Akun menunggu persetujuan Owner.':'Akses akun dinonaktifkan. Hubungi Owner demo.');if(a.role==='Operator'&&!db.employees.some(e=>e.id===a.employeeId&&e.active))throw Error('Profil karyawan nonaktif. Owner perlu meninjau akses.');if(a.role==='Konsumen'&&!db.tenants.some(t=>t.id===a.tenantId&&t.status==='Aktif'))throw Error('Profil penghuni belum aktif. Owner perlu meninjau akses.');sessionStorage.setItem(SESSION_KEY,a.id);session=a.id;event('Masuk ke ruang demo');save();ui.page='home';ui.tab='laundry';ui.search='';storyCleanup();location.hash='jurnal';render();window.scrollTo({top:0,behavior:'auto'});return;}
if(type==='signup'){const email=String(v.email).trim().toLowerCase();if(!/^[a-z0-9.!#$%&'*+/=?^_`{|}~-]+@tophills\.example$/.test(email))throw Error('Gunakan email fiktif berakhiran @tophills.example.');if(!['Operator','Konsumen'].includes(v.role))throw Error('Peran ini tidak bisa didaftarkan.');if(state.accounts.some(a=>a.email===email))throw Error('Email demo sudah terdaftar. Silakan masuk atau minta tinjauan Owner.');validatePassword(v.password);if(v.password!==v.confirm)throw Error('Ulangi kata sandi yang sama.');if(v.demo!=='on')throw Error('Konfirmasi penggunaan data fiktif.');const name=String(v.name).trim();if(name.length<2||name.length>60)throw Error('Isi nama fiktif 2–60 karakter.');const a=await makeAccount({id:uid('USER'),name,email,role:v.role,status:'Menunggu',employeeId:'',tenantId:''},v.password);state.accounts.push(a);event('Permintaan akun '+name+' · '+v.role);save();view='success';renderAccess();document.querySelector('.auth-panel h2')?.focus({preventScroll:true});return;}
if(type==='approve'){owner();const a=state.accounts.find(a=>a.id===formEl.dataset.id);if(!a||a.role==='Owner')throw Error('Akun tidak valid.');if(v.approved!=='on')throw Error('Konfirmasi bahwa lingkup akses sudah ditinjau.');const name=String(v.name).trim(),reason=String(v.reason).trim();if(name.length<2||name.length>60||reason.length<5)throw Error('Isi nama serta alasan peninjauan.');const profile=a.role==='Operator'?db.employees.find(e=>e.id===v.profileId&&e.active):db.tenants.find(t=>t.id===v.profileId&&t.status==='Aktif');if(!profile)throw Error('Pilih profil aktif.');const key=a.role==='Operator'?'employeeId':'tenantId';if(state.accounts.some(x=>x.id!==a.id&&x.status==='Aktif'&&x[key]===v.profileId))throw Error('Profil ini sudah memiliki akun aktif. Perbarui akun tersebut atau nonaktifkan akses lamanya.');const old=a.status;a[key]=v.profileId;a.name=name;a.status='Aktif';a.approvedAt=new Date().toISOString();a.approvedBy=current().id;event(a.email+': '+old+' → Aktif. '+reason);save();closeModal();render();manage();toast('Persetujuan akses demo tersimpan.');return;}
if(type==='revoke'){owner();const a=state.accounts.find(a=>a.id===formEl.dataset.id);if(!a||a.role==='Owner')throw Error('Akun ini tidak bisa dinonaktifkan.');const reason=String(v.reason).trim();if(reason.length<5)throw Error('Isi alasan penonaktifan.');a.status='Nonaktif';event(a.email+': akses dinonaktifkan. '+reason);save();closeModal();render();manage();return;}
}catch(e){state=JSON.parse(snapshot);session=oldSession;try{if(oldSession)sessionStorage.setItem(SESSION_KEY,oldSession);else sessionStorage.removeItem(SESSION_KEY);}catch{}error.textContent=e.message||'Belum tersimpan. Periksa isian dan penyimpanan browser.';submitBtn.disabled=false;}}
const accessActions={nav,fill(role){chosen=role;view='signin';renderAccess();const f=document.querySelector('[data-access-form=signin]');f.elements.password.value=DEMO_PASSWORD;f.querySelector('[type=submit]').focus({preventScroll:true});},password(_,b){const input=b.previousElementSibling,show=input.type==='password';input.type=show?'text':'password';b.textContent=show?'Sembunyikan':'Lihat';b.setAttribute('aria-label',show?'Sembunyikan kata sandi':'Tampilkan kata sandi');},profile,manage,review,skip(){document.querySelector('#masuk').scrollIntoView({behavior:'auto'});document.querySelector('.auth-panel h2')?.focus({preventScroll:true});},signout(){sessionStorage.removeItem(SESSION_KEY);session='';closeModal();nav('signin');},recovery(){openModal('Bantuan akun demo',`<p>Untuk akun contoh, gunakan kata sandi <b>${DEMO_PASSWORD}</b>.</p><p>Akun yang kamu daftarkan memakai kata sandi fiktif pilihanmu. Tidak ada pengiriman tautan reset email. Jika lupa, Owner dapat menonaktifkan akun lama; ajukan akun demo baru dengan email lain.</p><div class="notice blue">${icon('shield')}Pemulihan akun produksi belum terhubung. Jangan memasukkan kredensial asli.</div>`);},revoke(id){owner();const a=state.accounts.find(a=>a.id===id);if(!a||a.role==='Owner')throw Error('Akun ini tidak bisa dinonaktifkan.');openModal('Nonaktifkan akses?',`<p>Akun ${h(a.name)} tidak bisa masuk lagi. Riwayat dan laporannya tetap tersimpan.</p><form data-access-form="revoke" data-id="${a.id}" class="auth-form">${area('Alasan penonaktifan','reason','','required minlength="5" maxlength="300"')}<div class="form-error" role="alert"></div><button class="btn primary" type="submit">Nonaktifkan akses</button></form>`);},export(){owner();download('Top-Hills-Co-Arsip-Akun-Demo.json',JSON.stringify(state,null,2),'application/json');},import(){owner();document.querySelector('#access-import').click();}};
document.addEventListener('click',e=>{const b=e.target.closest('[data-access]');if(!b)return;e.preventDefault();try{accessActions[b.dataset.access]?.(b.dataset.id,b);}catch(err){toast(err.message);}});
document.addEventListener('submit',e=>{if(!e.target.matches('[data-access-form]'))return;e.preventDefault();submit(e.target);});
document.addEventListener('change',async e=>{if(e.target.id!=='access-import')return;try{owner();const f=e.target.files[0];if(!f)return;if(f.size>2000000)throw Error('Arsip akun maksimal 2 MB.');const v=JSON.parse(await f.text());const ids=new Set(),emails=new Set();if(v.version!==1||!Array.isArray(v.accounts)||!Array.isArray(v.events)||!v.accounts.some(a=>a.id==='demo-owner'&&a.role==='Owner'&&a.status==='Aktif'))throw Error('Format arsip akun tidak valid.');for(const a of v.accounts){if(!a.id||ids.has(a.id)||emails.has(a.email)||!a.name||!String(a.email).endsWith('@tophills.example')||!['Owner','Operator','Konsumen'].includes(a.role)||!['Aktif','Menunggu','Nonaktif'].includes(a.status)||!/^[a-f0-9]{64}$/.test(a.hash)||!/^[a-f0-9]{32}$/.test(a.salt)||a.role==='Owner'&&a.id!=='demo-owner')throw Error('Data akun di arsip tidak valid.');ids.add(a.id);emails.add(a.email);}window.THAccess.pendingImport=v;openModal('Pulihkan arsip akun?',`<p>${v.accounts.length} akun akan menggantikan daftar akun demo di browser ini. Ekspor daftar saat ini terlebih dahulu bila masih diperlukan. Data operasional tidak berubah.</p><div class="button-row"><button class="btn" data-action="close">Batal</button><button class="btn primary" data-access="confirm-import">Pulihkan dan keluar</button></div>`);}catch(err){toast(err.message)}});
accessActions['confirm-import']=()=>{owner();if(!THAccess.pendingImport)throw Error('Arsip tidak tersedia.');const old=state;try{state=THAccess.pendingImport;save();THAccess.pendingImport=null;accessActions.signout();toast('Arsip akun dipulihkan. Silakan masuk kembali.');}catch(e){state=old;throw e;}};
window.addEventListener('storage',e=>{if(e.key===ACCOUNTS_KEY){try{const v=JSON.parse(e.newValue);if(v?.version===1&&Array.isArray(v.accounts)&&Array.isArray(v.events)){state=v;closeModal();bind();render();}}catch{}}});
window.THAccess={current,bind,render:renderAccess,widget,manage,cleanup(){storyCleanup();document.body.classList.remove('on-entry');},pending:()=>state.accounts.filter(a=>a.status==='Menunggu').length};
async function init(){if(initError){renderAccess();return;}try{if(!state.accounts.length){state.accounts=await Promise.all([{id:'demo-owner',name:'Nadia Demo',email:'owner@tophills.example',role:'Owner',status:'Aktif'},{id:'demo-operator',name:'Mira Demo',email:'mira@tophills.example',role:'Operator',employeeId:'e1',status:'Aktif'},{id:'demo-consumer',name:'Alya Demo',email:'alya@tophills.example',role:'Konsumen',tenantId:'t1',status:'Aktif'}].map(a=>makeAccount(a,DEMO_PASSWORD)));save();}ready=true;if(location.hash==='#daftar')view='signup';render();if(loadWarning)toast(loadWarning);}catch(e){initError=e.message;renderAccess();}}
renderAccess();init();
})();
